      const bare = /^Then you (create|put|return|exile|search|sacrifice|look|reveal|scry|surveil|mill) /i.test(s) &&
        parseEffectSentence(s.replace(/^Then you (\w)/, (x, c) => c.toUpperCase()), 1);
