        const rest = parseEffects(m[1].charAt(0).toUpperCase() + m[1].slice(1));
        if (!rest.auto || !rest.effects.length) return null;
        return [{ op: 'ifCond', cond: { kind: 'topSharesTypeWithSelf' }, then: [{ op: 'may', then: rest.effects }] }];
