    if (/\bonly once each turn\b|\bDo this only once\b/i.test(body)) return null;
    const pieces = (/, $/.test(m[3]) ? m[3].split(/, /) : [m[3]]).map(x => x.trim()).filter(Boolean).concat([m[4].trim()]);
